from copy import deepcopy
from typing import Any, Callable


def build_environment(config: dict[str, Any], load_routes: Callable[[list[str]], list[tuple[str, Callable[..., Any]]]]) -> dict[str, Any]:
    if not isinstance(config, dict):
        raise ValueError("config must be a dictionary")
    required = {"view_root", "deployment", "diagnostics", "datastore", "route_modules"}
    if not required.issubset(config):
        raise ValueError("config is missing required keys")
    if not isinstance(config["view_root"], str) or not config["view_root"]:
        raise ValueError("view_root must be non-empty")
    if config["deployment"] not in {"development", "staging", "production"}:
        raise ValueError("invalid deployment")
    if not isinstance(config["diagnostics"], dict) or not isinstance(config["datastore"], dict):
        raise ValueError("diagnostics and datastore must be dictionaries")
    modules = config["route_modules"]
    if not isinstance(modules, list):
        raise ValueError("route_modules must be a list")
    if any(not isinstance(module, str) or not module for module in modules):
        raise ValueError("route module names must be non-empty strings")
    if len(set(modules)) != len(modules):
        raise ValueError("route modules must be unique")
    if not callable(load_routes):
        raise ValueError("load_routes must be callable")

    loaded = load_routes(sorted(modules))
    if not isinstance(loaded, list):
        raise ValueError("loader must return a list")
    paths: set[str] = set()
    for route in loaded:
        if not isinstance(route, tuple) or len(route) != 2:
            raise ValueError("each route must be a two-item tuple")
        path, handler = route
        if not isinstance(path, str) or not path or not callable(handler):
            raise ValueError("invalid route")
        if path in paths:
            raise ValueError("route paths must be unique")
        paths.add(path)

    return {
        "view_root": deepcopy(config["view_root"]),
        "deployment": deepcopy(config["deployment"]),
        "diagnostics": deepcopy(config["diagnostics"]),
        "datastore": deepcopy(config["datastore"]),
        "routes": deepcopy(loaded),
    }

